'use strict';

// Per-user receiver configuration, called by the existing team-access owner.
// Saving an address never verifies ownership, enables ingestion, changes Auth,
// or sends mail. A separate protected confirmation keeps the pilot CLOSED.
const crypto=require('node:crypto');
const {resolveProductActiveRole}=require('./product-active-role-contract');
const TENANT='alianzas-soluciones',COUNTRY='GT';
const PILOT=Object.freeze({scenarioId:10221181,connectionId:14756803,
  ownerUidSha256:'f612197b077c598edd61d757c1e2995be7a3b17300602ce4802bccefed216a72',
  mailboxSha256:'9b663847979724e9491e1c655da32a7cb17a5f6ed26dba352de1eb811254b23f',
  authorityBlob:'17da2d0d297e0b0f010d2da763fd3d3a0f664c54'});
const sha=value=>crypto.createHash('sha256').update(Buffer.isBuffer(value)?value:String(value),'utf8').digest('hex');
const stable=value=>value&&typeof value.toJSON==='function'?stable(value.toJSON()):Array.isArray(value)?value.map(stable):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(k=>[k,stable(value[k])])):value;
const digest=value=>sha(JSON.stringify(stable(value)));
const str=value=>typeof value==='string'?value.trim():'';
const uid=value=>/^[A-Za-z0-9_-]{1,128}$/.test(str(value));
class MailboxHold extends Error{constructor(code){super(code);this.code=code;}}
const need=(condition,code)=>{if(!condition)throw new MailboxHold(code);};
const row=snap=>snap&&snap.exists?snap.data():null;
const root=db=>db.collection('tenants').doc(TENANT);
const bindingRef=(db,ownerUid)=>root(db).collection('mailboxBindings').doc(ownerUid);
const memberRef=(db,ownerUid)=>root(db).collection('members').doc(ownerUid);
const ownerIndexRef=(db,mailboxSha256)=>root(db).collection('mailboxOwners').doc(mailboxSha256);
function address(value){
  need(typeof value==='string'&&value.length<=320,'MAILBOX_ADDRESS_INVALID');
  const result=value.trim().toLowerCase();
  need(/^[^\s<>@,;]+@[^\s<>@,;]+\.[^\s<>@,;]+$/.test(result)&&!/[\u0000-\u001f\u007f]/.test(result),'MAILBOX_ADDRESS_INVALID');
  return result;
}
function assertIdentity(member,user,ownerUid){
  need(uid(ownerUid)&&member&&member.tenantId===TENANT&&member.uid===ownerUid&&
    [member.id,member.userId].every(x=>x===undefined||x===null||x===''||x===ownerUid),'MAILBOX_MEMBER_IDENTITY_HOLD');
  const states=[member.status,member.estado].map(x=>str(x).toLowerCase()).filter(Boolean);
  need(states.length>0&&states.every(x=>['active','activo'].includes(x))&&
    member.active!==false&&member.activo!==false&&member.inactivo!==true&&member.deleted!==true&&member.eliminado!==true&&member.archivado!==true,
    'MAILBOX_MEMBER_INACTIVE');
  const countries=[].concat(member.countries||[],member.paises||[],member.pais||[],member.country||[]).map(x=>str(x).toUpperCase()).filter(Boolean);
  need(countries.includes(COUNTRY)&&countries.every(x=>['GT','CO'].includes(x)),'MAILBOX_MEMBER_COUNTRY_HOLD');
  need(user&&user.uid===ownerUid&&user.disabled===false&&user.emailVerified===true,'MAILBOX_AUTH_IDENTITY_HOLD');
  return true;
}
function targetUid(advisor){
  const ids=[...new Set([advisor.authUid,advisor.uid,advisor.userId].map(str).filter(Boolean))];
  need(ids.length===1&&uid(ids[0]),'MAILBOX_EXACT_USER_BINDING_REQUIRED');
  return ids[0];
}
function validateBinding(binding,ownerUid){
  if(binding===null)return;
  need(binding&&binding.schema==='GI_I66_PER_USER_MAILBOX_BINDING_V1'&&binding.tenantId===TENANT&&binding.country===COUNTRY&&
    binding.ownerUid===ownerUid&&Number.isSafeInteger(binding.revision)&&binding.revision>0&&
    binding.mailboxSha256===sha(address(binding.address))&&binding.outboundEnabled===false&&
    ['PENDING_VERIFICATION','VERIFIED_CLOSED'].includes(binding.state)&&binding.ingressEnabled===false,
    'MAILBOX_BINDING_STATE_HOLD');
}
function projection(binding){return binding?{address:binding.address,state:binding.state,revision:binding.revision,
  verified:binding.state==='VERIFIED_CLOSED',ingressEnabled:false,bindingSha256:digest(binding)}:
  {address:'',state:'NOT_CONFIGURED',revision:0,verified:false,ingressEnabled:false,bindingSha256:digest(null)};}
function candidateRecord({ownerUid,mailboxAddress,before,at,actorUid}){
  validateBinding(before,ownerUid);
  const normalized=address(mailboxAddress);
  return {schema:'GI_I66_PER_USER_MAILBOX_BINDING_V1',tenantId:TENANT,country:COUNTRY,ownerUid,
    address:normalized,mailboxSha256:sha(normalized),revision:(before?.revision||0)+1,
    state:'PENDING_VERIFICATION',ingressEnabled:false,outboundEnabled:false,
    createdAt:before?.createdAt||at,updatedAt:at,updatedByUid:actorUid};
}
async function managed({request,db,auth,authorize,locateAdvisor,now=()=>new Date().toISOString()}){
  need(request.data?.tenantId===TENANT,'MAILBOX_TENANT_HOLD');
  const operation=request.data.operation;
  need(['get_mailbox_binding','set_mailbox_address'].includes(operation),'MAILBOX_OPERATION_HOLD');
  // The existing owner decides which currently assigned human may manage users.
  const actor=await authorize(request,TENANT,operation);
  const located=await locateAdvisor(TENANT,request.data.advisorId);
  need(located?.snap?.exists&&located.ref?.path===`tenants/${TENANT}/data/asesores/items/${request.data.advisorId}`,
    'MAILBOX_CANONICAL_ADVISOR_REQUIRED');
  const advisor=located.data,ownerUid=targetUid(advisor),user=await auth.getUser(ownerUid);
  const [memberSnap,actorSnap,beforeSnap]=await Promise.all([
    memberRef(db,ownerUid).get(),memberRef(db,request.auth.uid).get(),bindingRef(db,ownerUid).get()]);
  const member=row(memberSnap),actorMember=row(actorSnap),before=row(beforeSnap);
  assertIdentity(member,user,ownerUid);validateBinding(before,ownerUid);
  need([member.advisorId,member.asesorId].map(str).filter(Boolean).length>0&&
    [member.advisorId,member.asesorId].map(str).filter(Boolean).every(x=>x===request.data.advisorId),'MAILBOX_ADVISOR_USER_RELATION_HOLD');
  if(operation==='get_mailbox_binding')return {ok:true,mailbox:projection(before),canonicalWrites:0,messagesSent:0};
  need(str(request.data.reason).length>=5,'MAILBOX_REASON_REQUIRED');
  need(request.data.expectedBindingSha256===digest(before),'MAILBOX_CONFIG_CAS_CHANGED');
  const desired=address(request.data.mailboxAddress);
  if(before?.address===desired)return {ok:true,mailbox:projection(before),reused:true,configurationWrites:0,messagesSent:0};
  const at=now(),next=candidateRecord({ownerUid,mailboxAddress:desired,before,at,actorUid:request.auth.uid});
  const requestId='mailbox_'+digest({ownerUid,before:digest(before),next:desired});
  const receipt=root(db).collection('configEvents').doc(requestId);
  await db.runTransaction(async tx=>{
    const [freshBinding,freshMember,freshActor,freshAdvisor,existing]=await Promise.all([
      tx.get(bindingRef(db,ownerUid)),tx.get(memberRef(db,ownerUid)),tx.get(memberRef(db,request.auth.uid)),tx.get(located.ref),tx.get(receipt)]);
    need(digest(row(freshActor))===digest(actorMember),'MAILBOX_ACTOR_CHANGED');
    need(digest(row(freshAdvisor))===digest(advisor),'MAILBOX_USER_LINK_CHANGED');
    need(digest(row(freshMember))===digest(member),'MAILBOX_MEMBER_CHANGED');
    assertIdentity(row(freshMember),user,ownerUid);
    if(existing.exists){need(existing.data().afterDigest===digest(next)&&digest(row(freshBinding))===digest(next),'MAILBOX_REPLAY_DRIFT');return;}
    need(digest(row(freshBinding))===digest(before),'MAILBOX_CONFIG_CAS_CHANGED');
    tx.set(bindingRef(db,ownerUid),next,{merge:false});
    tx.create(receipt,{schema:'GI_I66_MAILBOX_CONFIGURATION_EVENT_V1',tenantId:TENANT,operation,
      actorUidSha256:sha(request.auth.uid),ownerUidSha256:sha(ownerUid),mailboxSha256:sha(desired),
      beforeDigest:digest(before),afterDigest:digest(next),reasonSha256:sha(request.data.reason),
      previousVerifiedBindingClosed:before?.state==='VERIFIED_CLOSED',createdAt:at});
  });
  const actual=row(await bindingRef(db,ownerUid).get());
  need(digest(actual)===digest(next),'MAILBOX_CONFIG_READBACK_HOLD');
  return {ok:true,mailbox:projection(actual),configurationWrites:2,authWrites:0,canonicalBusinessWrites:0,messagesSent:0};
}
async function preparePilot({db,auth,mailboxAddress,now=()=>new Date().toISOString()}){
  need(sha(address(mailboxAddress))===PILOT.mailboxSha256,'MAILBOX_PILOT_ADDRESS_HOLD');
  const members=await root(db).collection('members').limit(201).get();
  need(members.docs.length<201,'MAILBOX_MEMBER_CENSUS_BOUND');
  const found=members.docs.filter(x=>sha(x.id)===PILOT.ownerUidSha256);
  need(found.length===1,'MAILBOX_PILOT_OWNER_UNIQUE_HOLD');
  const ownerUid=found[0].id,member=found[0].data(),user=await auth.getUser(ownerUid);
  assertIdentity(member,user,ownerUid);
  need(resolveProductActiveRole(member,'direccion').activeRole==='direccion','MAILBOX_PILOT_DIRECTION_REQUIRED');
  const [bs,os]=await Promise.all([bindingRef(db,ownerUid).get(),ownerIndexRef(db,PILOT.mailboxSha256).get()]);
  const before=row(bs),ownerIndex=row(os);validateBinding(before,ownerUid);
  need(!before||before.mailboxSha256===PILOT.mailboxSha256,'MAILBOX_PILOT_CONFIG_CHANGED');
  need(!ownerIndex||(ownerIndex.tenantId===TENANT&&ownerIndex.ownerUid===ownerUid&&ownerIndex.mailboxSha256===PILOT.mailboxSha256),'MAILBOX_OTHER_OWNER_HOLD');
  return {ownerUid,member,user,before,ownerIndex,mailboxAddress:address(mailboxAddress),observedAt:now(),
    beforeDigest:digest(before),memberDigest:digest(member),ownerIndexDigest:digest(ownerIndex)};
}
async function bindConfirmedPilot({db,auth,mailboxAddress,expectedBeforeDigest,gate,now=()=>new Date().toISOString()}){
  need(gate?.environment==='gravicentra-live-data-writes'&&gate.repository==='paulaosoriof86/orbit360-core'&&
    gate.ref==='refs/heads/recovery/fase-a-clean-20260831'&&gate.project==='ays-orbit-360-lab'&&
    gate.authorityBlob===PILOT.authorityBlob&&gate.ownerUidSha256===PILOT.ownerUidSha256&&
    gate.scenarioId===PILOT.scenarioId&&gate.connectionId===PILOT.connectionId,'MAILBOX_PROTECTED_SCOPE_HOLD');
  const prepared=await preparePilot({db,auth,mailboxAddress,now}),p=prepared;
  need(p.beforeDigest===expectedBeforeDigest,'MAILBOX_PILOT_CONFIG_CAS_CHANGED');
  const prior=p.before,at=now(),eventId='mailbox_verify_'+digest({ownerUid:p.ownerUid,before:expectedBeforeDigest,authority:PILOT.authorityBlob});
  const er=root(db).collection('configEvents').doc(eventId);
  const next=prior?.state==='VERIFIED_CLOSED'?prior:{
    ...candidateRecord({ownerUid:p.ownerUid,mailboxAddress,before:prior,at,actorUid:'integration:protected-mailbox-config'}),
    state:'VERIFIED_CLOSED',verification:{authorityBlob:PILOT.authorityBlob,ownerUidSha256:PILOT.ownerUidSha256,
      identityBasis:'EXPLICIT_OWNER_CONFIRMATION_AND_FRESH_MEMBERSHIP_AUTH',providerLoginIdentityVerified:false,
      ownerConfirmationAuthorityBlob:PILOT.authorityBlob,scenarioId:PILOT.scenarioId,
      connectionId:PILOT.connectionId,verifiedAt:at},ingressEnabled:false,outboundEnabled:false};
  const result=await db.runTransaction(async tx=>{
    const [bs,ms,os,es]=await Promise.all([tx.get(bindingRef(db,p.ownerUid)),tx.get(memberRef(db,p.ownerUid)),
      tx.get(ownerIndexRef(db,PILOT.mailboxSha256)),tx.get(er)]);
    need(digest(row(ms))===p.memberDigest,'MAILBOX_MEMBER_CHANGED');assertIdentity(row(ms),p.user,p.ownerUid);
    need(digest(row(os))===p.ownerIndexDigest,'MAILBOX_OTHER_OWNER_HOLD');
    need(digest(row(bs))===expectedBeforeDigest,'MAILBOX_PILOT_CONFIG_CAS_CHANGED');
    if(prior?.state==='VERIFIED_CLOSED'){
      need(prior.verification?.authorityBlob===PILOT.authorityBlob&&prior.verification?.scenarioId===PILOT.scenarioId&&
        prior.verification?.connectionId===PILOT.connectionId&&p.ownerIndex?.ownerUid===p.ownerUid,'MAILBOX_VERIFIED_BINDING_DRIFT');
      return {reused:true,configurationWrites:0};
    }
    need(!es.exists,'MAILBOX_AUDIT_WITHOUT_CONFIG_HOLD');
    tx.set(bindingRef(db,p.ownerUid),next,{merge:false});
    tx.set(ownerIndexRef(db,PILOT.mailboxSha256),{schema:'GI_I66_MAILBOX_OWNER_INDEX_V1',tenantId:TENANT,
      ownerUid:p.ownerUid,mailboxSha256:PILOT.mailboxSha256,authorityBlob:PILOT.authorityBlob},{merge:false});
    tx.create(er,{schema:'GI_I66_MAILBOX_VERIFIED_CLOSED_EVENT_V1',tenantId:TENANT,
      ownerUidSha256:PILOT.ownerUidSha256,mailboxSha256:PILOT.mailboxSha256,authorityBlob:PILOT.authorityBlob,
      beforeDigest:expectedBeforeDigest,afterDigest:digest(next),runId:String(gate.runId),createdAt:at});
    return {reused:false,configurationWrites:3};
  });
  const [bs,os]=await Promise.all([bindingRef(db,p.ownerUid).get(),ownerIndexRef(db,PILOT.mailboxSha256).get()]);
  need(digest(row(bs))===digest(next)&&row(os)?.ownerUid===p.ownerUid,'MAILBOX_PILOT_READBACK_HOLD');
  return {schema:'GI_I66_MAILBOX_PROTECTED_BINDING_READBACK_V1',status:'VERIFIED_CLOSED',
    ownerUidSha256:PILOT.ownerUidSha256,mailboxSha256:PILOT.mailboxSha256,
    scenarioId:PILOT.scenarioId,connectionId:PILOT.connectionId,beforeDigest:expectedBeforeDigest,afterDigest:digest(next),
    ...result,canonicalBusinessWrites:0,authWrites:0,mailReads:0,messagesSent:0,ingressEnabled:false};
}
module.exports={TENANT,COUNTRY,PILOT,sha,digest,address,MailboxHold,need,row,root,bindingRef,memberRef,ownerIndexRef,
  assertIdentity,targetUid,validateBinding,projection,candidateRecord,managed,preparePilot,bindConfirmedPilot};

'use strict';

// Transaction support for the canonical Ops/Leads owner, not another writer.
// No callable or provider endpoint exports this module. The existing owner must
// call fresh() before its writes, and record() in the SAME Firestore transaction.
// A source adapter must first persist the exact authenticated IMAP readback in
// the server-only source-proof collection. A browser payload cannot authorize it.
const b=require('./product-mailbox-binding');
const {sha,digest,need,row,root,bindingRef,memberRef}=b;
const str=x=>typeof x==='string'?x:'';
const refs=(db,ctx)=>({
  binding:bindingRef(db,ctx.ownerUid),member:memberRef(db,ctx.ownerUid),
  grant:root(db).collection('config').doc('mailIngress'),
  proof:root(db).collection('mailIngressSourceProofs').doc(ctx.sourceProofId),
  entity:root(db).collection('data').doc(ctx.entity.type).collection('items').doc(ctx.entity.id),
  access:root(db).collection('config').doc('access'),
  collision:root(db).collection('mailMessageIds').doc(ctx.messageIdKey),
  message:root(db).collection('mailMessages').doc(ctx.messageKey),
  delivery:root(db).collection('mailboxDeliveries').doc(ctx.ownerUid).collection('receipts').doc(ctx.deliveryKey),
  attachments:ctx.attachments.map(a=>root(db).collection('mailAttachmentJobs').doc(a.key))
});
function packetIdentity(packet){
  const mid=str(packet?.messageId).trim(),sender=b.address(packet?.fromAddress);
  need(/^<[^<>\s@]+@[^<>\s@]+>$/.test(mid)&&mid.length<=998,'MAIL_MESSAGE_ID_REQUIRED');
  need(typeof packet.text==='string'&&Buffer.byteLength(packet.text,'utf8')<=262144&&
    (packet.html===undefined||typeof packet.html==='string'&&Buffer.byteLength(packet.html,'utf8')<=524288),
    'MAIL_CONTENT_PROOF_REQUIRED');
  need(typeof packet.subject==='string'&&packet.subject.length<=2000,'MAIL_SUBJECT_HOLD');
  need(Buffer.byteLength(JSON.stringify({sender,subject:packet.subject,text:packet.text,html:packet.html||''}),'utf8')<=750000,
    'MAIL_FIRESTORE_CONTENT_BOUND');
  need(Array.isArray(packet.attachments)&&packet.attachments.length<=30,'MAIL_ATTACHMENT_BOUND');
  let total=0;
  const attachments=packet.attachments.map(a=>{
    need(Buffer.isBuffer(a.bytes)&&a.bytes.length>0&&a.bytes.length<=20000000&&typeof a.contentType==='string'&&
      a.contentType.length<=200&&typeof a.fileName==='string'&&a.fileName.length<=1000,'MAIL_ACTUAL_ATTACHMENT_BYTES_REQUIRED');
    total+=a.bytes.length;
    return {sha256:sha(a.bytes),size:a.bytes.length,contentType:a.contentType.toLowerCase(),
      key:digest({tenantId:b.TENANT,bytesSha256:sha(a.bytes)})};
  });
  need(total<=25000000,'MAIL_ATTACHMENTS_TOTAL_BOUND');
  // Order, filenames, recipients, Bcc/CC, Received, Return-Path and mailbox UIDs
  // cannot identify the business message. Actual decoded content is preserved.
  const content={sender,subject:packet.subject,textSha256:sha(packet.text),htmlSha256:sha(packet.html||''),
    attachments:attachments.map(({sha256,size,contentType})=>({sha256,size,contentType})).sort((a,c)=>digest(a).localeCompare(digest(c)))};
  const fingerprint=digest(content),messageIdKey=digest({tenantId:b.TENANT,messageId:mid});
  return {messageId:mid,messageIdKey,contentFingerprint:fingerprint,
    messageKey:digest({tenantId:b.TENANT,messageId:mid,fingerprint}),content,attachments};
}
function plan({binding,packet,sourceProofId,sourceProofDigest,entity,authUser,memberDigest,nowMs=Date.now()}){
  b.validateBinding(binding,binding?.ownerUid);
  need(binding?.state==='VERIFIED_CLOSED'&&binding.verification?.connectionId&&binding.verification?.scenarioId,
    'MAIL_VERIFIED_BINDING_REQUIRED');
  need(/^[A-Za-z0-9_-]{10,160}$/.test(str(sourceProofId))&&/^[a-f0-9]{64}$/.test(str(sourceProofDigest)),
    'MAIL_SERVER_SOURCE_PROOF_REQUIRED');
  need(['negocios','gestiones','clientes'].includes(entity?.type)&&/^[A-Za-z0-9][A-Za-z0-9._:-]{1,159}$/.test(str(entity.id))&&
    /^[a-f0-9]{64}$/.test(str(entity.beforeDigest)),'MAIL_CANONICAL_ENTITY_PROOF_REQUIRED');
  need(authUser?.uid===binding.ownerUid&&authUser.disabled===false&&authUser.emailVerified===true&&
    Number.isSafeInteger(authUser.observedAtMs)&&nowMs>=authUser.observedAtMs&&nowMs-authUser.observedAtMs<=30000,
    'MAIL_FRESH_OWNER_AUTH_REQUIRED');
  need(/^[a-f0-9]{64}$/.test(str(memberDigest)),'MAIL_FRESH_MEMBER_DIGEST_REQUIRED');
  const identity=packetIdentity(packet),bindingDigest=digest(binding);
  const deliveryKey=digest({tenantId:b.TENANT,ownerUid:binding.ownerUid,mailboxSha256:binding.mailboxSha256,messageKey:identity.messageKey});
  return {...identity,ownerUid:binding.ownerUid,bindingDigest,mailboxSha256:binding.mailboxSha256,
    connectionId:binding.verification.connectionId,scenarioId:binding.verification.scenarioId,
    sourceProofId,sourceProofDigest,entity,authUser,memberDigest,deliveryKey,
    eventId:'mail_evt_'+identity.messageKey.slice(0,40),nowMs,
    businessContent:{fromAddress:packet.fromAddress,subject:packet.subject,text:packet.text,html:packet.html||'',
      references:packet.references||[],inReplyTo:packet.inReplyTo||[]},
    privateObservation:{providerObservationSha256:digest(packet.providerObservation||{}),
      recipientsSha256:digest({to:packet.to||[],cc:packet.cc||[]}),attachmentNames:packet.attachments.map(a=>a.fileName)}};
}
async function fresh(tx,{db,ctx,nowMs=Date.now()}){
  const r=refs(db,ctx),s=await Promise.all([r.binding,r.member,r.grant,r.proof,r.collision,r.message,r.delivery,r.entity,r.access,...r.attachments].map(x=>tx.get(x)));
  const [binding,member,grant,proof,collision,message,delivery,entity,access,...attachments]=s.map(row);
  need(digest(binding)===ctx.bindingDigest,'MAIL_BINDING_CHANGED');
  b.validateBinding(binding,ctx.ownerUid);b.assertIdentity(member,ctx.authUser,ctx.ownerUid);
  need(digest(member)===ctx.memberDigest&&nowMs>=ctx.authUser.observedAtMs&&nowMs-ctx.authUser.observedAtMs<=30000,
    'MAIL_MEMBER_OR_AUTH_CHANGED');
  need(grant?.schema==='GI_I66_MAIL_INGRESS_GRANT_V1'&&grant.tenantId===b.TENANT&&grant.country===b.COUNTRY&&
    grant.state==='ACTIVE'&&grant.outboundEnabled===false&&grant.canonicalOwner==='functions/product-ops-leads-domain.js'&&
    Array.isArray(grant.allowedBindingDigests)&&grant.allowedBindingDigests.includes(ctx.bindingDigest),
    'MAIL_INGRESS_NOT_ACTIVE_FOR_BINDING');
  need(proof&&digest(proof)===ctx.sourceProofDigest&&proof.schema==='GI_I66_AUTHENTICATED_IMAP_SOURCE_PROOF_V1'&&
    proof.tenantId===b.TENANT&&proof.ownerUid===ctx.ownerUid&&proof.mailboxSha256===ctx.mailboxSha256&&
    proof.bindingDigest===ctx.bindingDigest&&proof.scenarioId===ctx.scenarioId&&proof.connectionId===ctx.connectionId&&
    proof.sourceKind==='SERVER_IMAP_READBACK'&&proof.senderAuthenticated===true&&
    proof.messageIdKey===ctx.messageIdKey&&proof.contentFingerprint===ctx.contentFingerprint&&
    proof.scopeAuthority==='EXISTING_CANONICAL_OWNER'&&proof.memberDigest===ctx.memberDigest&&proof.accessConfigDigest===digest(access)&&
    proof.businessEntity?.type===ctx.entity.type&&proof.businessEntity?.id===ctx.entity.id&&
    proof.businessEntity?.beforeDigest===ctx.entity.beforeDigest&&proof.entityScopeVerified===true,
    'MAIL_AUTHENTICATED_SOURCE_OR_ENTITY_PROOF_HOLD');
  need(entity&&entity.tenantId===b.TENANT&&entity.pais===b.COUNTRY&&(!entity.id||entity.id===ctx.entity.id)&&
    entity.deleted!==true&&entity.eliminado!==true&&entity.archivado!==true,'MAIL_CURRENT_ENTITY_SCOPE_HOLD');
  if(!message)need(digest(entity)===ctx.entity.beforeDigest,'MAIL_ENTITY_CAS_CHANGED');
  need(!collision||(collision.tenantId===b.TENANT&&collision.messageIdKey===ctx.messageIdKey&&
    collision.contentFingerprint===ctx.contentFingerprint&&collision.messageKey===ctx.messageKey),
    'MAIL_MESSAGE_ID_CONTENT_COLLISION');
  if(message)need(message.schema==='GI_I66_CANONICAL_BUSINESS_MAIL_V1'&&message.tenantId===b.TENANT&&
    message.messageKey===ctx.messageKey&&message.contentFingerprint===ctx.contentFingerprint&&
    message.entityType===ctx.entity.type&&message.entityId===ctx.entity.id&&message.eventId===ctx.eventId&&
    message.canonicalOwner==='functions/product-ops-leads-domain.js','MAIL_EXISTING_BUSINESS_RELATION_HOLD');
  need(!!collision===!!message,'MAIL_CANONICAL_LEDGER_INCOMPLETE');
  if(delivery)need(delivery.ownerUid===ctx.ownerUid&&delivery.mailboxSha256===ctx.mailboxSha256&&
    delivery.messageKey===ctx.messageKey&&delivery.deliveryKey===ctx.deliveryKey,'MAIL_PRIVATE_DELIVERY_DRIFT');
  attachments.forEach((a,i)=>{if(a)need(a.tenantId===b.TENANT&&a.originalSha256===ctx.attachments[i].sha256&&
    a.size===ctx.attachments[i].size&&a.processingOwner==='functions/cobros-source-intake-v2.js','MAIL_ATTACHMENT_JOB_DRIFT');});
  return {refs:r,collision,message,delivery,attachments,
    writeBusinessActivity:!message,canonicalResult:message?.canonicalResult||null};
}
function record(tx,{ctx,freshState,canonicalResult,createdAt}){
  const f=freshState,r=f.refs;
  need(typeof createdAt==='string'&&Number.isFinite(Date.parse(createdAt)),'MAIL_COMMIT_TIME_REQUIRED');
  if(!f.message){
