  function defaultPermissions() {
    const def = {};
    const roles = roleCatalog();
    roles.forEach(rol => {
      def[rol] = {};
      // The product membership contract uses modules/defaultScope, not legacy
      // `nivel`. Requiring that removed field silently rendered EVERY Edit
      // checkbox unchecked (including SuperAdmin) in the clean product.
      // This is only the initial matrix; the protected access document remains
      // the authority for all owner-configured Ver/Editar overrides.
      const nivel = Number(roleDefinition(rol)?.nivel||0);
      const fullAdmin = ['Dirección', 'SuperAdmin', 'AdminTenant', 'Admin'].includes(rol);
      const fullOperator = rol === 'Operativo';
      const assigned = new Set(baseModules([rol]));
      allModuleIds().forEach(m => {
        const admin = ['comisiones', 'finanzas', 'configuracion', 'equipo'].includes(m);
        const visible = assigned.has(m);
        def[rol][m] = {
          ver: visible,
          editar: visible && (fullAdmin || (fullOperator && !admin) || nivel >= (admin ? 4 : 2))
        };
      });
    });
    return def;
  }
  function defaultRoleScopes() {
    return { 'Dirección':'all','Admin':'all','AdminTenant':'all','SuperAdmin':'all','Finanzas':'all','Operativo':'all','Marketing':'team','Asesor':'own','Asistente':'team','Comercial':'own' };
  }
  function getAccessConfig() {
    try { const tenant=Orbit.tenant&&Orbit.tenant.get?Orbit.tenant.get():{},canonical=tenant&&tenant.domainConfig&&tenant.domainConfig.access;if(canonical&&typeof canonical==='object')return canonical; } catch(e){}
    return accessConfigCache||{};
  }
  function mergePermissionMatrix(base, overrides) {
    const out=JSON.parse(JSON.stringify(base||{}));
    Object.entries(overrides&&typeof overrides==='object'?overrides:{}).forEach(([role,mods])=>{
      out[role]=out[role]||{};
      Object.entries(mods&&typeof mods==='object'?mods:{}).forEach(([moduleKey,actions])=>{
        out[role][moduleKey]=Object.assign({},out[role][moduleKey]||{},actions&&typeof actions==='object'?actions:{});
      });
    });
    return out;
  }
  function getPermisos() {
    const base=defaultPermissions();
