'use strict';
const assert=require('node:assert/strict');
class MemoryDb{
  constructor(){this.docs=new Map();this.version=0;this.commits=0;}
  doc(path){const db=this;return {path,id:path.split('/').at(-1),collection:n=>db.collection(path+'/'+n),
    get:async()=>db.snapshot(path),get parent(){return db.collection(path.split('/').slice(0,-1).join('/'));}};}
  collection(path,bound=Infinity){const db=this;return {path,bound,isCollection:true,doc:id=>db.doc(path+'/'+id),limit:n=>db.collection(path,n),
    get:async()=>({docs:db.query(path,bound)})};}
  query(path,bound){return [...this.docs.keys()].filter(k=>k.startsWith(path+'/')&&!k.slice(path.length+1).includes('/')).slice(0,bound).map(k=>this.snapshot(k));}
  snapshot(path){const v=this.docs.get(path);return {id:path.split('/').at(-1),exists:!!v,ref:this.doc(path),data:()=>v?structuredClone(v.value):undefined};}
  seed(path,value){this.docs.set(path,{value:structuredClone(value),version:++this.version});}
  async runTransaction(fn){
    for(let attempt=0;attempt<8;attempt++){
      const reads=new Map(),queries=new Map(),writes=[];let started=false;
      const tx={get:async r=>{assert.equal(started,false,'Firestore transaction cannot read after writing');
        if(r.isCollection){queries.set(r.path,JSON.stringify([...this.docs].filter(([k])=>k.startsWith(r.path+'/')).map(([k,v])=>[k,v.version])));await Promise.resolve();return {docs:this.query(r.path,r.bound)};}
        reads.set(r.path,this.docs.get(r.path)?.version||0);await Promise.resolve();return this.snapshot(r.path);},
        create:(r,v)=>{started=true;writes.push({op:'create',path:r.path,value:structuredClone(v)});},
        set:(r,v)=>{started=true;writes.push({op:'set',path:r.path,value:structuredClone(v)});},
        update:(r,v)=>{started=true;writes.push({op:'update',path:r.path,value:structuredClone(v)});}};
      const result=await fn(tx);
      if([...reads].some(([p,v])=>(this.docs.get(p)?.version||0)!==v)||[...queries].some(([p,v])=>JSON.stringify([...this.docs].filter(([k])=>k.startsWith(p+'/')).map(([k,v])=>[k,v.version]))!==v))continue;
      const all=new Map(this.docs);
      for(const w of writes){if(w.op==='create')assert.equal(all.has(w.path),false,'duplicate create');
        if(w.op==='update')assert.equal(all.has(w.path),true,'missing update');
        all.set(w.path,{value:w.op==='update'?{...all.get(w.path).value,...w.value}:w.value,version:++this.version});}
      this.docs=all;if(writes.length)this.commits++;return result;
    }
    throw Error('MEMORY_TRANSACTION_RETRY_EXHAUSTED');
  }
  values(collection){return [...this.docs].filter(([p])=>p.includes('/'+collection+'/')).map(([p,v])=>({path:p,...v.value}));}
}
module.exports={MemoryDb};

